/* ---------- data ---------- */
async function loadMine(){var r=await sb.rpc("bb_get",{p_fighter:null});if(r.error)throw r.error;S.rec=r.data;S.ev=S.rec?RB.evaluate(S.rec,CFG.event.date,today()):null;}
async function loadAll(){var r=await sb.rpc("bb_all");if(r.error)throw r.error;S.all=(r.data||[]).map(function(x){x.ev=RB.evaluate(x.record,CFG.event.date,today());return x;});}
async function save(field,value){
  var key=field;S.saving[key]="saving";S.err[key]="";paintSave(key);
  try{RB.validateParticipantEdit(S.rec,field,value,today());}catch(e){S.saving[key]="err";S.err[key]=e.message;paintSave(key);T(e.message);return false;}
  var r=await sb.rpc("bb_participant_update",{p_field:field,p_value:value});
  if(r.error){S.saving[key]="err";S.err[key]=r.error.message;paintSave(key);T("Couldn't save: "+r.error.message);return false;}
  S.rec=r.data;S.ev=RB.evaluate(S.rec,CFG.event.date,today());S.saving[key]="ok";paintSave(key);setTimeout(function(){if(S.saving[key]==="ok"){S.saving[key]="";paintSave(key);}},1800);
  return true;
}
function paintSave(key){var el=document.querySelector('[data-sv="'+key+'"]');if(el){var s=S.saving[key];el.className="sv"+(s==="err"?" err":s==="ok"?" ok":"");el.textContent=s==="saving"?"Saving…":s==="ok"?"Saved":s==="err"?"Not saved":"";el.title=S.err[key]||"";}}

/* ---------- participant UI ---------- */
function chip(code){var m={action_required:["Action required","amber"],pending_csa:["Pending CSA","blue"],awaiting_book:["Awaiting book","blue"],awaiting_final_review:["Awaiting Legacy review","teal"],needs_attention:["Needs attention","red"],paperwork_reviewed:["Paperwork reviewed","teal"]}[code]||[code,""];return '<span class="chip '+m[1]+'">'+esc(m[0])+'</span>';}
function appChip(st){var cls=st==="submitted"?"blue":st==="approved"?"teal":st==="more_information"||st==="refused"?"red":st==="draft"?"amber":"";return '<span class="chip '+cls+'">'+esc(RB.APP_TEXT[st]||st)+'</span>';}
function stepChip(id){var s=RB.stepState(S.rec,id,today());if(s.changes)return '<span class="chip red">Changes required</span>';if(s.checked)return '<span class="chip teal">Checked</span>';if(s.reported)return '<span class="chip blue">Reported done</span>';if(s.partial)return '<span class="chip amber">In progress</span>';return '<span class="chip">Not started</span>';}
function linkBtns(keys){return '<div class="links">'+keys.map(function(k){return '<a href="'+CFG.links[k]+'" target="_blank" rel="noopener">'+esc(CFG.linkNames[k]||k)+' ↗</a>';}).join("")+'</div>';}
function bool(field,label,sub){var on=!!S.rec[field];return '<div class="task"><div class="cb'+(on?' on':'')+'" role="checkbox" aria-checked="'+on+'" tabindex="0" aria-label="'+esc(label)+'" onclick="bbTog(\''+field+'\')" onkeydown="if(event.key===\' \'||event.key===\'Enter\'){event.preventDefault();bbTog(\''+field+'\')}">'+(on?'✓':'')+'</div><label onclick="bbTog(\''+field+'\')">'+esc(label)+(sub?'<small>'+esc(sub)+'</small>':'')+'</label><span class="sv" data-sv="'+field+'"></span></div>';}
function dateRow(field,label,sub){var v=S.rec[field]||"";var on=!!RB.parseDate(v);return '<div class="task"><div class="cb'+(on?' on':'')+'" aria-hidden="true">'+(on?'✓':'')+'</div><label for="bb-'+field+'">'+esc(label)+(sub?'<small>'+esc(sub)+'</small>':'')+'</label><input type="date" id="bb-'+field+'" value="'+esc(v)+'" onchange="bbDate(\''+field+'\',this.value)" aria-label="'+esc(label)+' date"><span class="sv" data-sv="'+field+'"></span></div>';}
function textRow(field,label,placeholder){return '<div class="task"><label for="bb-'+field+'" style="flex:0 0 38%">'+esc(label)+'</label><input type="text" id="bb-'+field+'" value="'+esc(S.rec[field]||"")+'" placeholder="'+esc(placeholder||"")+'" maxlength="60" onchange="bbText(\''+field+'\',this.value)" style="flex:1"><span class="sv" data-sv="'+field+'"></span></div>';}
function selRow(field,label,opts){return '<div class="task"><label for="bb-'+field+'" style="flex:0 0 38%">'+esc(label)+'</label><select id="bb-'+field+'" onchange="bbText(\''+field+'\',this.value)" style="flex:1">'+opts.map(function(o){return '<option value="'+esc(o[0])+'"'+(S.rec[field]===o[0]?' selected':'')+'>'+esc(o[1])+'</option>';}).join("")+'</select><span class="sv" data-sv="'+field+'"></span></div>';}
