  var h='<div class="bb"><button class="back" onclick="bbBack()">‹ Fight Club</button><div class="head"><img src="'+FC_LOGO+'" alt=""><div><div class="k">Fight Night · 19 Dec</div><div class="t">Your Blue Book</div></div></div>';
