     +'<div class="yn three" role="group" aria-label="Blue Book"><button class="'+(b==="none"?'on no':'')+'" onclick="bbBook(\'none\')">Not yet</button><button class="'+(b==="pending"?'on mid':'')+'" onclick="bbBook(\'pending\')">Pending</button><button class="'+(b==="received"?'on':'')+'" onclick="bbBook(\'received\')">Received</button></div><span class="sv" data-sv="q-book"></span></div>'
     +(b==="received"||b==="replacing"?'<p class="note">Lost or damaged it? <a href="'+CFG.links.replaceBook+'" target="_blank" rel="noopener" style="color:var(--blue)">Replace it on Service NSW</a> ($50) and tell Jake.</p>':'')+'</div>';
    if(ev.bloodReviewOn&&CFG.event.date>ev.bloodReviewOn)h+='<div class="warn">Your bloods run out on '+fmt(ev.bloodReviewOn)+', before fight night. You\'ll need them done again.</div>';
