  all.forEach(function(x){var r=x.record,ev=x.ev;if(ev.paperworkReviewed)c.reviewed++;if(r.applicationStatus==="submitted")c.pending++;if((r.applicationStatus==="approved"||(r.route==="existing"&&r.registrationNumber))&&!RB.verified(r,"registration"))c.reported++;if(r.bookStatus!=="received")c.nobook++;if(ev.issues.some(function(i){return /renew|expiry|boundary/.test(i.code);}))c.renew++;if(ev.status==="needs_attention")c.attention++;});
